import data from "./infrastructure.json" with { type: "json" };

/**
 * Addresses that must never act as linking funders or ancestors (exchanges, bridges, routers,
 * treasuries). Generated by `pnpm infra:scan` from on-chain activity, plus manual entries. These are
 * heuristics, not labels: each entry records why it qualified. Nansen labels will extend this.
 */
export interface InfraEntry {
  address: string;
  source: "heuristic" | "manual";
  reason: string;
  nonce?: number;
  balanceMon?: number;
  checkedBlock?: number;
}

/** Heuristic thresholds for "exchange-like": either one qualifies. */
export const INFRA_MIN_NONCE = 5_000;
export const INFRA_MIN_BALANCE_MON = 1_000_000;

export function isExchangeLike(nonce: number, balanceMon: number): boolean {
  return nonce >= INFRA_MIN_NONCE || balanceMon >= INFRA_MIN_BALANCE_MON;
}

/** Bundled at build time (the Worker has no filesystem); re-run `pnpm infra:scan` and redeploy to update. */
export function loadInfrastructure(): InfraEntry[] {
  return data as InfraEntry[];
}

export function infrastructureSet(): Set<string> {
  return new Set(loadInfrastructure().map((e) => e.address.toLowerCase()));
}
